-- RID=26 | MODULE=3 | MENU=4 | ITEM=1 | RQUERY=1 | NAME=Daftar Mutasi Barang (TS) | FILE=listtransferstock
SELECT ts.tsid , ts.tsnotransaksi , ts.tstgl , wa.wnama AS tsgudangasal , wt.wnama AS tsgudangtransit, wtu.wnama AS tsgudangtujuan, ts.tsuraian , st.nama AS tsstatus , b.bkode , tsd.namabarang , tsd.jml , tsd.satuan , tsd.catatan , mr.mrnotransaksi FROM m3_ts ts JOIN m1_warehouse wa ON ts.tsgudangasal = wa.wkode JOIN m1_warehouse wt ON ts.tsgudangtransit = wt.wkode JOIN m1_warehouse wtu ON ts.tsgudangtujuan = wtu.wkode JOIN m0_status st ON ts.tsstatus = st.kode JOIN m3_ts_detail tsd ON ts.tsid = tsd.idts JOIN m1_item b ON tsd.idbarang = b.bid LEft JOIN m3_mr_detail mrd ON mrd.idmrdetail = tsd.idmrdetail LEFt JOIN m3_mr mr ON mrd.idmr = mr.mrid ORDER BY ts.tstgl , ts.tsid , ts.tsnotransaksi , tsd.urutan;

-- RID=27 | MODULE=3 | MENU=4 | ITEM=2 | RQUERY=1 | NAME=Mutasi Barang (TS) | FILE=transferstockdetail_new
SELECT ts.tsid , ts.tsnotransaksi , ts.tstgl , wa.wnama AS tsgudangasal , wt.wnama AS tsgudangtransit, wtu.wnama AS tsgudangtujuan, ts.tsuraian , st.nama AS tsstatus , b.bkode , tsd.namabarang , tsd.jml , tsd.satuan , tsd.catatan , mr.mrnotransaksi FROM m3_ts ts LEFT JOIN m1_warehouse wa ON ts.tsgudangasal = wa.wkode LEFT JOIN m1_warehouse wt ON ts.tsgudangtransit = wt.wkode LEFT JOIN m1_warehouse wtu ON ts.tsgudangtujuan = wtu.wkode JOIN m0_status st ON ts.tsstatus = st.kode JOIN m3_ts_detail tsd ON ts.tsid = tsd.idts JOIN m1_item b ON tsd.idbarang = b.bid LEft JOIN m3_mr_detail mrd ON mrd.idmrdetail = tsd.idmrdetail LEFt JOIN m3_mr mr ON mrd.idmr = mr.mrid ORDER BY ts.tstgl , ts.tsid , ts.tsnotransaksi , tsd.urutan;

-- RID=716 | MODULE=3 | MENU=4 | ITEM=3 | RQUERY=1 | NAME=Mutasi Barang (TS) | FILE=transferstockdetail_new2
SELECT ts.tsid , ts.tsnotransaksi , ts.tstgl , wa.wnama AS tsgudangasal , wt.wnama AS tsgudangtransit, wtu.wnama AS tsgudangtujuan, ts.tsuraian , st.nama AS tsstatus , b.bkode , tsd.namabarang , tsd.jml , tsd.satuan , tsd.catatan , mr.mrnotransaksi FROM m3_ts ts LEFT JOIN m1_warehouse wa ON ts.tsgudangasal = wa.wkode LEFT JOIN m1_warehouse wt ON ts.tsgudangtransit = wt.wkode LEFT JOIN m1_warehouse wtu ON ts.tsgudangtujuan = wtu.wkode JOIN m0_status st ON ts.tsstatus = st.kode JOIN m3_ts_detail tsd ON ts.tsid = tsd.idts JOIN m1_item b ON tsd.idbarang = b.bid LEft JOIN m3_mr_detail mrd ON mrd.idmrdetail = tsd.idmrdetail LEFt JOIN m3_mr mr ON mrd.idmr = mr.mrid ORDER BY ts.tstgl , ts.tsid , ts.tsnotransaksi , tsd.urutan;

-- RID=29 | MODULE=3 | MENU=4 | ITEM=4 | RQUERY=1 | NAME=Mutasi Barang (TS)  | FILE=transferstockperlocation
SELECT tsd.urutan, b.bid , LEFT((blg.blgkodelokasi),3) AS lokasi, blg.blgnamalokasi, ts.tsnotransaksi , ts.tsstatus, ts.tstgl, tsd.namabarang, gt.wnama AS 'gudangtujuan', ga.wnama AS 'gudangasal', b.bkode, tsd.tipebarang, sum(tsd.jml), tsd.satuan, ts.tscatatan FROM m3_ts ts JOIN m3_ts_detail tsd ON (ts.tsid = tsd.idts) JOIN m1_item b ON (tsd.idbarang = b.bid) LEFT JOIN m1_warehouse gt ON (tsd.gudangtujuan = gt.wkode) LEFT JOIN m1_warehouse ga ON (tsd.gudangasal = ga.wkode) LEFT JOIN m1_item_location_warehouse blg ON (ts.tsgudangtransit = blg.blggudang AND b.bid = blg.blgidbarang) GROUP BY ts.tsnotransaksi, ifnull(LEFT((blg.blgkodelokasi),3), '-'), b.bkode , tsd.tipebarang , tsd.namabarang , tsd.satuan ORDER BY ts.tsnotransaksi, ifnull(LEFT((blg.blgkodelokasi),3), '-'), tsd.urutan;

