-- RID=35 | MODULE=3 | MENU=5 | ITEM=8 | RQUERY=1 | NAME=Terima Mutasi (RS) | FILE=receiptstockperlocation
SELECT rsd.urutan, rs.rsnotransaksi, LEFT((blg.blgnamalokasi),3) AS lokasi , rs.rstgl, rsd.jml, rsd.tipebarang, rsd.namabarang, rsd.satuan, b.bkode, blg.blgnamalokasi, rsd.catatan, rs.rscatatan FROM m3_rs rs JOIN m3_rs_detail rsd ON (rs.rsid = rsd.idrs) JOIN m1_item b ON (rsd.idbarang = b.bid) LEFT JOIN m1_item_location_warehouse blg ON (rs.rsgudangtransit = blg.blggudang) AND (b.bid = blg.blgidbarang) GROUP BY rs.rsnotransaksi, ifnull(LEFT((blg.blgnamalokasi),3), '-'), b.bkode , rsd.tipebarang , rsd.namabarang , blg.blgnamalokasi, rsd.satuan ORDER BY rs.rsnotransaksi, ifnull(LEFT((blg.blgnamalokasi),3), '-') , rsd.urutan;

