SELECT sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , b.bkode , sad.namabarang , tsa.tsanama AS sajenis , sp.spnotransaksi , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, (sad.jmlmasuk * sad.hpp) AS totalmasuk , (sad.jmlkeluar * sad.hpp) AS totalkeluar FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

