-- RID=201 | MODULE=3 | MENU=6 | ITEM=6 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) Per Produk | FILE=liststockadjustment_product
SELECT w.wnama AS gudang , b.bid , b.bkode , sad.namabarang , sa.satgl, sa.sanotransaksi , tsa.tsanama AS sajenis , sp.spnotransaksi , sad.satuan , SUM(sad.jmlmasuk) AS jmlkeluar , SUM(sad.jmlkeluar) AS jmlkeluar, SUM(sad.hpplama) AS hpplama, SUM(sad.hpp) AS hpp FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid GROUP BY sad.idbarang, b.bid, b.bkode, sad.namabarang, sad.satuan, sad.hpplama, sad.hpp ORDER BY sa.sagudang , sad.idbarang , b.bid , sad.namabarang;

-- RID=566 | MODULE=3 | MENU=6 | ITEM=7 | RQUERY=1 | NAME=Transaksi Barang (SA) | FILE=stockadjustmentdetail_ud
SELECT sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , sa.sauraian , tsa.tsanama AS sajenis , st.nama AS sastatus, sa.sacatatan , b.bkode , sad.namabarang , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, sad.catatan FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m0_status st ON sa.sastatus = st.kode ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=200 | MODULE=3 | MENU=6 | ITEM=8 | RQUERY=1 | NAME=Transaksi Barang (SA) | FILE=liststockadjustmentperakun
SELECT sad.reklawan, c.cnama, sa.sanotransaksi, sa.satgl, sa.sauraian, sad.hpp, sad.jmlmasuk, sad.jmlkeluar, sa.sacatatan, sad.satuan, b.bkode, sad.namabarang, sad.tipebarang, tsa.tsanama AS jenis FROM m3_sa sa JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_coa c ON sad.reklawan = c.cnomor LEFT JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode ORDER BY sad.reklawan , sa.sanotransaksi , sad.urutan;

-- RID=790 | MODULE=3 | MENU=6 | ITEM=9 | RQUERY=1 | NAME=Transaksi Barang (SA) | FILE=stockadjustmentdetail_newvolume
SELECT sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , sa.sauraian , tsa.tsanama AS sajenis , st.nama AS sastatus, sa.sacatatan , b.bkode , sad.namabarang , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, sad.catatan , b.balebar , b.bapanjang , b.batinggi , CASE sad.jmlkeluar when 0 then (sad.jmlmasuk * b.balebar * b.bapanjang * b.batinggi) else (sad.jmlkeluar * b.balebar * b.bapanjang * b.batinggi) END as volume FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m0_status st ON sa.sastatus = st.kode ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=791 | MODULE=3 | MENU=6 | ITEM=10 | RQUERY=1 | NAME=Transaksi Barang (SA) | FILE=stockadjustmentdetail_newvolume2
SELECT sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , sa.sauraian , tsa.tsanama AS sajenis , st.nama AS sastatus, sa.sacatatan , b.bkode , sad.namabarang , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, sad.catatan , b.balebar , b.bapanjang , b.batinggi , CASE sad.jmlkeluar when 0 then (sad.jmlmasuk * b.balebar * b.bapanjang * b.batinggi) else (sad.jmlkeluar * b.balebar * b.bapanjang * b.batinggi) END as volume FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m0_status st ON sa.sastatus = st.kode ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=1572 | MODULE=3 | MENU=6 | ITEM=11 | RQUERY=1 | NAME=Transaksi Barang (Detail) | FILE=DaftarPenyesuaianDetail
SELECT tsa.tsanama AS sajenis , sa.satgl , sa.sanotransaksi , k.knama AS sabagiansa, sa.sauraian , sad.namabarang , sad.jmlbarangmasuk as jmlmasuk , sad.satuanbarang , sad.hpp , (sad.jmlbarangmasuk * sad.hpp) as nilai FROM m3_sa sa JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_contact k ON sa.sabagiansa = k.kid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode ORDER BY sa.satgl;

-- RID=1593 | MODULE=3 | MENU=6 | ITEM=12 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) Per Jenis | FILE=liststockadjustment_perjenis
SELECT br.bnama AS sacabang , l.lnama AS salokasi , sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , b.bkode , sad.namabarang , tsa.tsanama AS sajenis , sp.spnotransaksi , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, (sad.jmlmasuk * sad.hpp) AS totalmasuk , (sad.jmlkeluar * sad.hpp) AS totalkeluar FROM m3_sa sa LEFT JOIN m1_branch br ON sa.sacabang = br.bkode LEFT JOIN m1_location l ON sa.salokasi = l.lkode AND sa.sacabang = l.lcabang JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid ORDER BY br.bnama , l.lnama , sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=1592 | MODULE=3 | MENU=6 | ITEM=13 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) Per Kontak | FILE=liststockadjustment_perkontak
SELECT k.knama AS sabagiansa, sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , b.bkode , sad.namabarang , sa.sabagiansa AS grup , tsa.tsanama AS sajenis , sp.spnotransaksi , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp , IF(((sad.jmlmasuk - sad.jmlkeluar) * sad.hpp) < 0,((sad.jmlmasuk - sad.jmlkeluar) * sad.hpp) * -1,((sad.jmlmasuk - sad.jmlkeluar) * sad.hpp) * 1) as total FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid JOIN m1_contact k ON sa.sabagiansa = k.kid ORDER BY sa.sagudang , sa.sabagiansa, sa.satgl, sa.said, sa.sanotransaksi , sad.urutan;

-- RID=1603 | MODULE=3 | MENU=6 | ITEM=14 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) | FILE=liststockadjustment_2
SELECT sa.sagudang , w.wnama AS gudang, sa.sanotransaksi , sa.satgl , b.bkode , sad.namabarang , tsa.tsanama AS sajenis , sp.spnotransaksi , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, (sad.jmlmasuk * sad.hpp) AS totalmasuk , (sad.jmlkeluar * sad.hpp) AS totalkeluar FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=1686 | MODULE=3 | MENU=6 | ITEM=15 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) Global | FILE=liststockadjustmentglobal
SELECT sa.said, sa.sanotransaksi , sa.satgl , k.knama AS sabagiansa, sa.sagudang , w.wnama AS gudang, tsa.tsanama AS sajenis , sa.sauraian, s.nama AS sastatus, b.bkode , sad.namabarang , sp.spnotransaksi , sad.satuan , sad.jmlmasuk , sad.jmlkeluar, sad.hpplama, sad.hpp, (sad.jmlmasuk * sad.hpp) AS totalmasuk , (sad.jmlkeluar * sad.hpp) AS totalkeluar , sa.samodifikasitgl FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m1_contact k ON sa.sabagiansa = k.kid JOIN m0_status s ON sa.sastatus = s.kode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=1687 | MODULE=3 | MENU=6 | ITEM=16 | RQUERY=1 | NAME=Daftar Transaksi Barang (SA) Detail | FILE=liststockadjustmentdetail
SELECT sa.said, sa.sanotransaksi , sa.satgl , k.knama AS sabagiansa, sa.sagudang , w.wnama AS gudang, tsa.tsanama AS sajenis , sa.sauraian, s.nama AS sastatus, b.bkode , sad.namabarang , sp.spnotransaksi , sad.satuanbarang as satuan , sad.jmlbarangmasuk as jmlmasuk , sad.jmlbarangkeluar as jmlkeluar, sad.hpplama, sad.hpp, (sad.jmlbarangmasuk * sad.hpp) AS totalmasuk , (sad.jmlbarangkeluar * sad.hpp) AS totalkeluar, b.bkategori as kategoribarang, ic.icnama as namakategoribarang FROM m3_sa sa JOIN m1_warehouse w ON sa.sagudang = w.wkode JOIN m3_sa_detail sad ON sa.said = sad.idsa JOIN m1_item b ON sad.idbarang = b.bid JOIN m1_type_sa tsa ON sa.sajenis = tsa.tsakode JOIN m1_contact k ON sa.sabagiansa = k.kid JOIN m0_status s ON sa.sastatus = s.kode LEFT JOIN m3_sp_detail spd ON sad.idspdetail = spd.idspdetail LEFT JOIN m3_sp sp ON spd.idsp = sp.spid left join m1_item_category ic on b.bkategori = ic.ickode ORDER BY sa.sagudang , sa.satgl , sa.said, sa.sanotransaksi , sad.urutan;

-- RID=50001654 | MODULE=3 | MENU=6 | ITEM=17 | RQUERY=1 | NAME=Tansaksi SA | FILE=StockAdjustment
SELECT said, sacabang, salokasi, sagudang, sasumber, sajenis, saautonotransaksi, sanotransaksi, satgl, sakodepa, sabagiansa, sabagiansakontak, sauraian, sacatatan, sanoref, satglnoref, said, sastatus, sastatussebelumnya, sajmlrevisi, sacetakanke, sainputuser, sainputtgl, samodifikasiuser, samodifikasitgl, saposting, sapostingtgl, satutupperiode, saisclose, sauploaded, idsadetail, idsa, idbarang, namabarang, tipebarang, jmlmasuk, jmlkeluar, satuan, nilaisatuan, jmlbarangmasuk, jmlbarangkeluar, satuanbarang, idhppkhususmasuk, hpplama, hpp, rekpersediaan, reklawan, idspdetail, cabang, lokasi, gudang, costcenter,divisi,subdivisi, proyek, catatan, urutan, isclose FROM FROM m3_sa sa JOIN m3_sa_detail sad ON sa.said = sad.idsa ORDER BY sa.satgl ASC, sa.said ASC , sad.idsadetail ASC;

-- RID=43 | MODULE=3 | MENU=7 | ITEM=1 | RQUERY=1 | NAME=Daftar Stok Opname (SP) | FILE=liststockopname
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlfisik , spd.jmlbagus , spd.jmlrusak, (spd.jmlsistem - spd.jmlfisik ) AS jmlselisih FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.urutan;

-- RID=48 | MODULE=3 | MENU=7 | ITEM=2 | RQUERY=1 | NAME=Daftar Stok Opname (SP) Outstanding | FILE=liststockopnameoutstanding
SELECT sp.spnotransaksi , sp.sptgl , w.wnama AS spgudang , sp.spuraian , st.nama AS spstatus , il.ilnama as lokasibarang , b.bkode , spd.namabarang , spd.satuan , spd.jmlsistem, spd.jmlsa, (spd.jmlsistem - spd.jmlsa) AS sisa FROM m3_sp sp JOIN m1_warehouse w ON sp.spgudang = w.wkode JOIN m0_status st ON sp.spstatus = st.kode JOIN m3_sp_detail spd ON sp.spid = spd.idsp JOIN m1_item b ON spd.idbarang = b.bid LEFT JOIN m1_item_location il ON spd.lokasibarang = il.ilkode AND sp.spgudang = il.ilgudang ORDER BY sp.sptgl , sp.spid , sp.spnotransaksi , spd.urutan;

